use serde_json::{json,Value};
use std::{collections::HashMap,sync::Mutex,time::{Instant,Duration}};
static ACTIVE:Mutex<Vec<(String,u64,Instant)>>=Mutex::new(Vec::new());
fn own()->Value{serde_json::from_str(include_str!(concat!(env!("ELIO_EXTENSION_ROOT"),"/core/build-info.json"))).expect("build identity")}
pub fn seen(q:&HashMap<String,String>){if let (Some(b),Some(p))=(q.get("build_id"),q.get("protocol").and_then(|p|p.parse().ok())){if !b.is_empty()&&b.len()<100&&b.bytes().all(|b|b.is_ascii_alphanumeric()||b"-_ .".contains(&b)){let mut rows=ACTIVE.lock().unwrap_or_else(|e|e.into_inner());rows.retain(|(old,op,at)|at.elapsed()<Duration::from_secs(120)&&(old!=b||*op!=p));if rows.len()>=16{rows.remove(0);}rows.push((b.clone(),p,Instant::now()));}}}
pub fn snapshot()->Value{let o=own();let mut rows=ACTIVE.lock().unwrap_or_else(|e|e.into_inner());rows.retain(|(_,_,at)|at.elapsed()<Duration::from_secs(120));let bad:Vec<_>=rows.iter().filter(|(b,p,_)|Some(b.as_str())!=o["build_id"].as_str()||Some(*p)!=o["protocol"].as_u64()).map(|(b,_,_)|b.as_str()).collect();let warning=if bad.is_empty(){String::new()}else{format!("App build {} differs from active extension build(s): {}. Update/reload the matching extension and refresh AI tabs.",o["build_id"].as_str().unwrap(),bad.join(", "))};json!({"app":o,"extensions":rows.iter().map(|(b,p,_)|json!({"build_id":b,"protocol":p})).collect::<Vec<_>>(),"warning":warning})}
#[cfg(test)]mod tests{use super::*;#[test]fn matching_browser_cannot_hide_old_extension(){let mut q=HashMap::new();q.insert("build_id".into(),"old".into());q.insert("protocol".into(),"1".into());seen(&q);let o=own();q.insert("build_id".into(),o["build_id"].as_str().unwrap().into());q.insert("protocol".into(),"2".into());seen(&q);assert!(!snapshot()["warning"].as_str().unwrap().is_empty());assert_eq!(snapshot()["extensions"].as_array().unwrap().len(),2);}}
